konsole_tabs:
/* Generated by ~/.config/plasma-rice/rice.py from the wallpaper palette. Do not edit. */
QTabBar { background: rgba(14,16,14, 217); }
QTabBar::tab {
    background: transparent; color: #777c78;
    border: 1px solid transparent; border-radius: 10px;
    padding: 4px 12px; margin: 8px 2px 2px 2px;
    min-width: 7em; max-width: 22em;
}
QTabBar::tab:first { margin-left: 12px; }
QTabBar::tab:hover:!selected { background: rgba(223,226,224, 20); color: #aeb2af; }
QTabBar::tab:selected {
    background: rgba(199,204,200, 41); color: #dfe2e0;
    border-color: rgba(199,204,200, 82);
}

zen:
/* Rice for Zen: generated by ~/.config/plasma-rice/apps.py from the wallpaper palette. Do not edit. */
:root, :host(:is(.anonymous-content-host, notification-message)) {
  --zen-primary-color: #c7ccc8 !important;
  --zen-branding-dark: #0e100e !important;
  --zen-colors-primary: color-mix(in srgb, #c7ccc8 22%, #121413) !important;
  --zen-colors-secondary: color-mix(in srgb, #c7ccc8 32%, #121413) !important;
  --zen-colors-tertiary: #080a08 !important;
  --zen-colors-hover-bg: color-mix(in srgb, #c7ccc8 14%, #161816) !important;
  --zen-colors-primary-foreground: #dfe2e0 !important;
  --zen-colors-border: rgba(58,62,59, 0.55) !important;
  --zen-colors-border-contrast: rgba(58,62,59, 0.3) !important;
  --zen-colors-input-bg: #161816 !important;
  --zen-input-border-color: #3a3e3b !important;
  --zen-dialog-background: #121413 !important;
  --zen-urlbar-background: #161816 !important;
  --zen-main-browser-background: linear-gradient(135deg, rgba(44,46,45, 0.72) 0%, rgba(8,10,8, 0.84) 52%, rgba(44,46,44, 0.68) 100%) !important;
  --zen-main-browser-background-toolbar: linear-gradient(135deg, rgba(44,46,45, 0.72) 0%, rgba(8,10,8, 0.84) 52%, rgba(44,46,44, 0.68) 100%) !important;
  --toolbox-textcolor: #dfe2e0 !important;
  --toolbar-field-color: #dfe2e0 !important;
  --arrowpanel-background: #161816 !important;
  --arrowpanel-color: #dfe2e0 !important;
  --arrowpanel-border-color: rgba(58,62,59, 0.6) !important;
  --panel-separator-color: rgba(58,62,59, 0.6) !important;
  --focus-outline-color: #c7ccc8 !important;
  --zen-sidebar-themed-icon-fill: #aeb2af !important;
}

/* Zen paints the workspace gradient on these layers and sets its variables inline on them,
   so override the layers themselves (::before is the cross-fade target while switching spaces) */
.zen-browser-generic-background::after,
.zen-browser-generic-background::before {
  background: linear-gradient(135deg, rgba(44,46,45, 0.72) 0%, rgba(8,10,8, 0.84) 52%, rgba(44,46,44, 0.68) 100%) !important;
}

/* selected tab: a soft accent wash with a hairline, instead of plain white */
.tabbrowser-tab:is([selected], [multiselected]) .tab-background {
  background-color: rgba(199,204,200, 0.16) !important;
  box-shadow: inset 0 0 0 1px rgba(199,204,200, 0.32) !important;
}
.tabbrowser-tab:not([selected]):hover .tab-background {
  background-color: rgba(223,226,224, 0.07) !important;
}

/* command bar / url bar popup */
#urlbar[breakout-extend] > .urlbar-background,
#urlbar[breakout-extend] #urlbar-background {
  background-color: #161816 !important;
  border: 1px solid rgba(58,62,59, 0.7) !important;
  box-shadow: 0 12px 40px rgba(0, 0, 0, 0.45) !important;
}
.urlbarView-row[selected] {
  background-color: rgba(199,204,200, 0.18) !important;
}

/* menus and popups */
menupopup, panel {
  --panel-background: #161816 !important;
  --panel-color: #dfe2e0 !important;
  --panel-border-color: rgba(58,62,59, 0.6) !important;
}
/* Rice for Zen: generated by ~/.config/plasma-rice/apps.py. Do not edit. */
:root {
  scrollbar-color: rgba(99,103,100, 0.7) transparent;
}
@-moz-document url("about:blank"), url("about:newtab"), url("about:home"), url("about:privatebrowsing") {
  html, body { background-color: #0e100e !important; }
}
